/* ── Midline integration overrides: ensure hero + sec_quality render full-screen without relying on common.js bootstrap that the original site provides ── */
.sub_visual.background{--maskT:0%;--maskR:0%;--maskB:0%;--maskL:0%;--opacity:0;--y:0%}
.sub_visual .title h2{opacity:1}
.sec_quality{transform:none}
.sec_quality .clip_wrap{--maskT:0%;--maskR:0%;--maskB:0%;--maskL:0%;--round:0;opacity:1}


/* ── Full-bleed override: force component to viewport edges regardless of parent constraints ── */
#wrap.intro.company.about{position:relative;left:50%;right:50%;margin-left:-50vw;margin-right:-50vw;width:100vw;max-width:100vw;background:#fff}
#wrap.intro.company.about .container,#wrap.intro.company.about .content,#wrap.intro.company.about #triggerGroup,#wrap.intro.company.about #triggerGroup .sticky,#wrap.intro.company.about .sec,#wrap.intro.company.about .sec_enc,#wrap.intro.company.about .sec_quality,#wrap.intro.company.about .sec_portfolio,#wrap.intro.company.about .sec_wonder,#wrap.intro.company.about .sec_business,#wrap.intro.company.about .sub_visual{width:100%;max-width:100%;margin-left:0;margin-right:0}

/* ── Floating back button on the bare company-info route. Lives outside #wrap so it floats above all sections. The button rule from the leaked Ssangyong CSS applies plain `button{...}` so we win via the `.cip-back` class + scoped properties. ── */
button.cip-back{position:fixed;top:24px;left:24px;z-index:9999;display:inline-flex;align-items:center;gap:8px;padding:10px 22px;background:rgba(80,207,254,.10);border:1px solid rgba(80,207,254,.30);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border-radius:999px;font-family:var(--font-body),system-ui,sans-serif;font-size:14px;font-weight:600;letter-spacing:.06em;color:#50CFFE;line-height:1;cursor:pointer;transition:transform 160ms cubic-bezier(0.23,1,0.32,1),background 200ms ease,border-color 200ms ease}
button.cip-back span{font-size:16px;line-height:1}
button.cip-back:active{transform:scale(0.97)}
@media (hover:hover) and (pointer:fine){button.cip-back:hover{background:rgba(80,207,254,.16);border-color:rgba(80,207,254,.50)}}
@media (max-width:768px){button.cip-back{top:16px;left:16px;padding:8px 16px;font-size:13px}}

/* ── Print PDF button — lives in the hero breadcrumb row, mirrors the back button glassmorphism. Positioned absolutely so it sits to the right of the breadcrumb without disturbing the title block beneath. ── */
.sub_visual .top{position:relative}
a.cip-print-pdf, button.cip-print-pdf{position:absolute;top:60px;right:0;z-index:5;display:inline-flex;align-items:center;gap:8px;padding:10px 22px;background:rgba(80,207,254,.10);border:1px solid rgba(80,207,254,.30);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border-radius:999px;font-family:var(--font-body),system-ui,sans-serif;font-size:14px;font-weight:600;letter-spacing:.06em;color:#50CFFE;line-height:1;cursor:pointer;text-decoration:none;transition:transform 160ms cubic-bezier(0.23,1,0.32,1),background 200ms ease,border-color 200ms ease}
a.cip-print-pdf, button.cip-print-pdf span{font-size:16px;line-height:1}
a.cip-print-pdf, button.cip-print-pdf:active{transform:scale(0.97)}
@media (hover:hover) and (pointer:fine){a.cip-print-pdf, button.cip-print-pdf:hover{background:rgba(80,207,254,.16);border-color:rgba(80,207,254,.50)}}
@media (max-width:768px){a.cip-print-pdf, button.cip-print-pdf{padding:8px 16px;font-size:13px}}

